    public void handleOrderBook(Client client, Map<String, Object> message)
    {
        // { type: "orderbook",
        //   "code": "BTC-ETH",
        //   "timestamp": 1584486737444,
        //   "total_ask_size": 16.76384456,
        //   "total_bid_size": 168.9020623,
        //   "orderbook_units":
        //    [ { ask_price: 0.02295077,
        //        "bid_price": 0.02161249,
        //        "ask_size": 3.57100696,
        //        "bid_size": 22.5303265 },
        //      { ask_price: 0.02295078,
        //        "bid_price": 0.02152658,
        //        "ask_size": 0.52451651,
        //        "bid_size": 2.30355128 },
        //      { ask_price: 0.02295086,
        //        "bid_price": 0.02150802,
        //        "ask_size": 1.585,
        //        "bid_size": 5 }, ... ],
        //   "stream_type": "SNAPSHOT" }
        String marketId = this.safeString(message, "code");
        String symbol = this.safeSymbol(marketId, null, "-");
        String type = this.safeString(message, "stream_type");
        Map<String, Object> options = (Map<String, Object>) this.safeDict(this.options, "watchOrderBook", new HashMap<String, Object>() {{}});
        Long limit = this.safeInteger(options, "limit", 15);
        if (java.util.Objects.equals(type, "SNAPSHOT"))
        {
            Helpers.addElementToObject(this.orderbooks, symbol, this.orderBook(new HashMap<String, Object>() {{}}, limit));
        }
        io.github.ccxt.ws.WsOrderBook orderbook = (io.github.ccxt.ws.WsOrderBook) ((Map<?, ?>)this.orderbooks).get(symbol);
        // upbit always returns a snapshot of 15 topmost entries
        // the "REALTIME" deltas are not incremental
        // therefore we reset the orderbook on each update
        // and reinitialize it again with new bidasks
        orderbook.reset(new HashMap<String, Object>() {{}});
        Helpers.addElementToObject(orderbook, "symbol", symbol);
        io.github.ccxt.ws.OrderBookSide bids = (io.github.ccxt.ws.OrderBookSide) Helpers.GetValue(orderbook, "bids");
        io.github.ccxt.ws.OrderBookSide asks = (io.github.ccxt.ws.OrderBookSide) Helpers.GetValue(orderbook, "asks");
        List<Object> data = (List<Object>) this.safeList(message, "orderbook_units", new ArrayList<Object>(Arrays.asList()));
        for (var i = 0; i < ((List<?>)data).size(); i++)
        {
            Map<String, Object> entry = (Map<String, Object>) this.safeDict(data, i);
            Double ask_price = this.safeFloat(entry, "ask_price");
            Double ask_size = this.safeFloat(entry, "ask_size");
            Double bid_price = this.safeFloat(entry, "bid_price");
            Double bid_size = this.safeFloat(entry, "bid_size");
            asks.store(ask_price, ask_size);
            bids.store(bid_price, bid_size);
        }
        Long timestamp = this.safeInteger(message, "timestamp");
        String datetime = this.iso8601(timestamp);
        Helpers.addElementToObject(orderbook, "timestamp", timestamp);
        Helpers.addElementToObject(orderbook, "datetime", datetime);
        String messageHash = ("orderbook:" + symbol);
        client.resolve(orderbook, messageHash);
    }

    public void handleTrades(Client client, Map<String, Object> message)
    {
        // { type: "trade",
        //   "code": "KRW-BTC",
        //   "timestamp": 1584508285812,
        //   "trade_date": "2020-03-18",
        //   "trade_time": "05:11:25",
        //   "trade_timestamp": 1584508285000,
        //   "trade_price": 6747000,
        //   "trade_volume": 0.06499468,
        //   "ask_bid": "ASK",
        //   "prev_closing_price": 6774000,
        //   "change": "FALL",
        //   "change_price": 27000,
        //   "sequential_id": 1584508285000002,
        //   "stream_type": "REALTIME" }
        Map<String, Object> trade = (Map<String, Object>) this.parseTrade(message);
        String symbol = (String) ((Map<String, Object>)trade).get("symbol");
        if (java.util.Objects.equals(symbol, null))
        {
            return;
        }
        io.github.ccxt.ws.ArrayCache stored = (io.github.ccxt.ws.ArrayCache) this.safeValue(this.trades, symbol);
        if (java.util.Objects.equals(stored, null))
        {
            Long limit = this.safeInteger(this.options, "tradesLimit", 1000);
            stored = new ArrayCache(((Number)limit).intValue());
            Helpers.addElementToObject(this.trades, symbol, stored);
        }
        stored.append(trade);
        String messageHash = ("trade:" + symbol);
        client.resolve(stored, messageHash);
    }

